package com.nexus.property.notification;import com.nexus.property.auth.*;import com.nexus.property.core.*;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController{private final Db db;public NotificationController(Db db){this.db=db;}private Map<String,Object>map(Map<String,Object>r){return Map.of("id",Rows.s(r,"id"),"type",Rows.s(r,"type"),"title",Rows.s(r,"title"),"message",Rows.s(r,"message"),"referenceId",Objects.toString(Rows.s(r,"reference_id"),""),"isRead",Rows.b(r,"is_read"),"createdAt",Rows.l(r,"created_at"));}@GetMapping public Map<String,Object>list(HttpServletRequest r){var u=AuthFilter.require(r);var a=db.all("SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100",u.userId()).stream().map(this::map).toList();return Api.ok("Notifications retrieved.",a);}@PostMapping("/{id}/read")public Map<String,Object>read(HttpServletRequest r,@PathVariable String id){var u=AuthFilter.require(r);db.exec("UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?",id,u.userId());return Api.message("Notification marked as read.");}@PostMapping("/read-all")public Map<String,Object>all(HttpServletRequest r){var u=AuthFilter.require(r);db.exec("UPDATE notifications SET is_read=1 WHERE user_id=?",u.userId());return Api.message("All notifications marked as read.");}}
